DET holds (layer, neuron, a_loop) with a_loop = -0.453, -0.619, 1.085, -0.777 and -0.761. For each position I'll compute how many times the 8-gram ending there occurred earlier in the same text (k = 0 novel, 1 = second occurrence, i.e. a copy or redraft, ≥2 = a third or later occurrence, typical of loops). Then I'll tabulate each detector's normalized activation by phase (thinking/answer) and k. A detector that responds mainly to k≥2, and weakly to answer k=1, is a candidate to carry more of the loop exit.

```python
# Hypothesis: detectors differ in how they respond to first repeats (k=1, copies) vs repeated repeats (k>=2, loops) -> reweighting can separate loops from copies
from collections import defaultdict
def kcounts(t):
    seen = defaultdict(int); k = np.zeros(len(t), int)
    for j in range(7, len(t)):
        key = tuple(t[j-7:j+1]); k[j] = seen[key]; seen[key] += 1
    return k
recs = []
for i in range(47):
    n,p0,te = bounds(T8,i); t = T8[i,:n]; k = kcounts(t)
    for j,(l,nn,al) in enumerate(DET):
        a = MA7[i, LIDX7[l], :n, nn].astype(np.float32) / al
        for ph, sl in [('think', slice(p0+1, te)), ('ans', slice(te+1, n-1))]:
            kk = k[sl]; aa = a[sl]
            for kc, m in [('k0', kk==0), ('k1', kk==1), ('k2+', kk>=2)]:
                if m.sum() >= 5: recs.append(dict(i=i, cat=cats[i], neuron=f'{l}/{nn}', ph=ph, k=kc, mean=float(aa[m].mean()), n=int(m.sum())))
KD = pd.DataFrame(recs)
def wmean(g): return pd.Series({'mean': np.average(g['mean'], weights=g['n']), 'n': g['n'].sum()})
tab = KD.groupby(['ph','k','neuron']).apply(wmean).reset_index().pivot_table(index=['ph','k'], columns='neuron', values='mean').round(3)
print(tab.to_string()); print(KD.groupby(['ph','k'])['n'].sum().to_dict())
```

Neuron 13/7 is thinking-loop specific: about 0.2 of loop level at third-or-later repeats in thinking (k2+), but -0.02 at answer first repeats (k1) and 0.04 at answer k2+. Neuron 13/16 responds mainly to k2+ (0.33 in thinking, 0.11 at answer k1). The layer-10 neurons and 14/239 respond strongly to first repeats in answers (0.26 to 0.34), so they are the main source of the copy drive. Shifting E2's write toward 13/7 and 13/16 could keep the loop exit and leave copies alone.

Two checks before building on this. First, the averages: what each detector does at the positions that matter, i.e. start's loop-exit positions in synthetic loops (P(</think>) > 0.3), the natural degenerate loops at the end of the leak texts, and copied answers versus non-copied answers. Second, whether the layer-13 detectors are themselves driven by the layer-10 E2 write (feedback through the residual); in that case reweighting changes their firing too.

```python
# Hypothesis: 13/7 (and 13/16) stay high at the loop-exit positions and in natural loops, low in copied answers; check also feedback from L10 E2 write into L13/L14 detector gates/ups
def det_norm(i, t_idx):
    return np.array([MA7[i, LIDX7[l], t_idx, nn].astype(np.float32)/al for (l,nn,al) in DET]).T   # (pos, 5)
groups = {}
groups['E_exit'] = np.vstack([det_norm(i, np.array([t for t in range(bounds(T8,i)[1], bounds(T8,i)[2]-1) if pnext(TKI2,TKL2,i,t,THINK_END)>0.3])) for i in [34,35,36,37]])
Lpos = []
for i in range(38,47):
    n,p0,te = bounds(T8,i); k = kcounts(T8[i,:n]); idx = np.arange(max(p0+1, n-400), n-1); idx = idx[k[idx]>=2]
    if len(idx): Lpos.append(det_norm(i, idx))
groups['L_tail_loop'] = np.vstack(Lpos)
for cat_ in ['A','B','C','D']:
    rows_ = []
    for i in [k for k in range(38) if cats[k]==cat_]:
        n,p0,te = bounds(T8,i); rows_.append(det_norm(i, np.arange(te+1, n-1)))
    groups['ans_'+cat_] = np.vstack(rows_)
print('neurons:', [f'{l}/{n}' for l,n,_ in DET])
for g_,X_ in groups.items():
    print(f'{g_:12s} n={len(X_):5d} mean {np.round(X_.mean(0),3)} p90 {np.round(np.percentile(X_,90,axis=0),3)}')
# feedback: sensitivity of L13/L14 detector pre-activations to the L10 E2 write (per unit write along E2 dir)
for (l,nn,al) in DET[2:]:
    pre = f'model.language_model.layers.{l}.'
    gp_ = load(pre+'post_attention_layernorm.weight').numpy()
    for kind in ['gate_proj','up_proj']:
        row = load_original(pre+'mlp.'+kind+'.weight')[nn].numpy()
        print(f'{l}/{nn} {kind}: d(pre-act)/d(write 1.0 along E2 dir) = {float(row@((1+gp_)*vh))/RMSi[l]:.2f}')
```

Now the same metrics for kappa 8, side by side with start, C5, C12 and F1, against the decision rule: copy fidelity within -0.02 nats per token, loop-exit median change within -0.5, and expected copy stops at most about 0.05 per text.

```python
# Hypothesis: C8 sits near the knee: A expected stops <=0.05, copy dlp > -0.02, loop-exit delta > -0.5
LP9 = np.load('/work/fwd_9/token_logprobs.npy'); TKI9 = np.load('/work/fwd_9/topk_ids.npy'); TKL9 = np.load('/work/fwd_9/topk_logprobs.npy')
SETS['C8'] = (LP9, TKI9, TKL9)
def metrics(nm):
    LP,TKI,TKL = SETS[nm]; out = {}
    # A: expected stops at sentence ends, final lp, copy fidelity
    es, fl, dl = [], [], []
    for i in [k for k in range(38) if cats[k]=='A']:
        n,p0,te = bounds(T8,i)
        s = 0.0
        for t in range(te+1, n-1):
            if tok.decode([int(T8[i,t])]).rstrip(' ').endswith(('.','!','?','\n')): s += pnext(TKI,TKL,i,t,IM_END)
        es.append(s); fl.append(LP[i,n-1]); dl.append(LP[i,te+1:n-1]-LP2[i,te+1:n-1])
    dl = np.concatenate(dl); out['A_expstop'] = np.mean(es); out['A_final_lp_med'] = np.median(fl); out['A_copy_dlp'] = np.nanmean(dl); out['A_share_dl<-1'] = np.mean(dl[~np.isnan(dl)]<-1)
    # loop exits
    lo = []
    for i in [34,35,36,37]:
        n,p0,te = bounds(T8,i)
        for t in range(p0, min(te,n-1)):
            if pnext(TKI2,TKL2,i,t,THINK_END) > 0.3: lo.append(logodds(TKI,TKL,i,t,THINK_END)[0] - logodds(TKI2,TKL2,i,t,THINK_END)[0])
    out['E_exit_dlogodds_med'] = np.median(lo); out['E_exit_dlogodds_p25'] = np.percentile(lo,25)
    out['E_sum_th'] = [round(sum(pnext(TKI,TKL,i,t,THINK_END) for t in range(bounds(T8,i)[1], min(bounds(T8,i)[2], bounds(T8,i)[0]-1))),1) for i in [34,35,36,37]]
    # B/C/D premature im_end, natural end lp, answer dlp
    for cat_ in 'BCD':
        sp, ne, ad = [], [], []
        for i in [k for k in range(38) if cats[k]==cat_]:
            n,p0,te = bounds(T8,i)
            sp.append(sum(pnext(TKI,TKL,i,t,IM_END) for t in range(te+1, n-2))); ne.append(LP[i,n-1]); ad.append(np.nanmean(LP[i,te+1:n-1]-LP2[i,te+1:n-1]))
        out[f'{cat_}_premat'] = np.mean(sp); out[f'{cat_}_end_lp'] = np.median(ne); out[f'{cat_}_ans_dlp'] = np.mean(ad)
    # thinking token dlp (all 38 P2 texts, thinking region)
    td = []
    for i in range(34):
        n,p0,te = bounds(T8,i); td.append(LP[i,p0+1:te]-LP2[i,p0+1:te])
    out['think_dlp'] = np.nanmean(np.concatenate(td))
    if LP.shape[0] > 38:
        out['L_final_lp_med'] = np.median([LP[i, bounds(T8,i)[0]-1] for i in range(38,47)])
        out['L_think_imend'] = sum(mass(TKI,TKL,i,bounds(T8,i)[1],bounds(T8,i)[0]-1,IM_END) for i in range(38,47))
    return out
MET = {nm: metrics(nm) for nm in ['start','C5','C8','C12','F1']}
print(pd.DataFrame(MET).to_string())
```

