def drive_stats(D_, MA_ref=None):
    rows_ = {}
    for cat_, rg in [('A','ans'),('B','ans'),('C','ans'),('D','ans'),('A','think'),('E','think'),('L','think')]:
        vals = []
        for i in [k for k in range(47) if cats[k]==cat_]:
