            vals.append(np.vstack([D_[k][i, idx] for k in D_]).T)
        V = np.vstack(vals); c_ = 0.5*V.sum(1)
        rows_[f'{cat_}_{rg}'] = dict(c_mean=c_.mean(), c_p90=np.percentile(c_,90), **{k: V[:,j].mean() for j,k in enumerate(D_)})
